patches.diff:
From 675d0506ed2baa3f0d6cc4dff026a7bf01d1d6e6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:08:49 +0100
Subject: [PATCH] applet: let users mark a new Wi-Fi network as metered when
 connecting

Marking a network as metered was only possible in the connection editor,
so most people never did it. The password prompt for a new network now
has a "Metered connection" checkbox that is saved with the connection.

BUG: 479317
---
 applet/ConnectionItem.qml | 18 +++++++++++++++++-
 libs/handler.cpp          |  9 ++++++---
 libs/handler.h            |  6 ++++--
 3 files changed, 27 insertions(+), 6 deletions(-)

diff --git a/applet/ConnectionItem.qml b/applet/ConnectionItem.qml
index e2a79fd2f..fab0b9318 100644
--- a/applet/ConnectionItem.qml
+++ b/applet/ConnectionItem.qml
@@ -223,6 +223,7 @@ PlasmaExtras.ExpandableListItem {
         ColumnLayout {
             property alias password: passwordField.text
             property alias passwordField: passwordField
+            property alias metered: meteredCheckBox.checked

             PasswordField {
                 id: passwordField
@@ -254,6 +255,21 @@ PlasmaExtras.ExpandableListItem {
                     setDelayModelUpdates(true)
                 }
             }
+
+            RowLayout {
+                Layout.leftMargin: Kirigami.Units.gridUnit
+                Layout.rightMargin: Kirigami.Units.gridUnit
+                spacing: Kirigami.Units.smallSpacing
+
+                PlasmaComponents3.CheckBox {
+                    id: meteredCheckBox
+                    text: i18nc("@option:check", "Metered connection")
+                }
+
+                Kirigami.ContextualHelpButton {
+                    toolTipText: i18nc("@info:tooltip", "Apps and system updates can avoid downloading large amounts of data on metered connections, such as mobile hotspots or networks with a data limit.")
+                }
+            }
         }
     }

@@ -282,7 +298,7 @@ PlasmaExtras.ExpandableListItem {
                 } else if (connectionItem.customExpandedViewContent == passwordDialogComponent) {
                     const item = connectionItem.customExpandedViewContentItem;
                     if (item && item.password !== "") {
-                        handler.addAndActivateConnection(model.DevicePath, model.SpecificPath, item.password)
+                        handler.addAndActivateConnection(model.DevicePath, model.SpecificPath, item.password, item.metered)
                         connectionItem.customExpandedViewContent = detailsComponent
                         connectionItem.collapse()
                     } else {
diff --git a/libs/handler.cpp b/libs/handler.cpp
index 1a8d79746..6eaba9b7e 100644
--- a/libs/handler.cpp
+++ b/libs/handler.cpp
@@ -269,12 +269,12 @@ void Handler::requestWifiCode(const QString &connectionPath, const QString &ssid
     });
 }

-void Handler::addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password)
+void Handler::addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password, bool metered)
 {
-    addAndActivateConnectionInternal(device, specificParameter, password);
+    addAndActivateConnectionInternal(device, specificParameter, password, metered);
 }

-QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, const QString &specificObject, const QString &password)
+QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, const QString &specificObject, const QString &password, bool metered)
 {
     NetworkManager::AccessPoint::Ptr ap;
     NetworkManager::WirelessDevice::Ptr wifiDev;
@@ -297,6 +297,9 @@ QCoro::Task<> Handler::addAndActivateConnectionInternal(const QString &device, c
     settings->setId(ap->ssid());
     settings->setUuid(NetworkManager::ConnectionSettings::createNewUuid());
     settings->setAutoconnect(true);
+    if (metered) {
+        settings->setMetered(NetworkManager::ConnectionSettings::MeteredYes);
+    }

     UiUtils::setConnectionDefaultPermissions(settings);

diff --git a/libs/handler.h b/libs/handler.h
index 64a8425de..b5295f04f 100644
--- a/libs/handler.h
+++ b/libs/handler.h
@@ -71,12 +71,13 @@ public Q_SLOTS:
      * @device - d-bus path of the wireless device where the connection should be activated
      * @specificParameter - d-bus path of the accesspoint you want to connect to
      * @password - pre-filled password which should be used for the new wireless connection
+     * @metered - whether the new wireless connection should be marked as metered
      * @autoConnect - boolean value whether this connection should be activated automatically when it's available
      *
      * Works automatically for wireless connections with WEP/WPA security, for wireless connections with WPA/WPA
      * it will open the connection editor for advanced configuration.
      * */
-    void addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password = QString());
+    void addAndActivateConnection(const QString &device, const QString &specificParameter, const QString &password = QString(), bool metered = false);

     /**
      * Request a code that includes the credentials to a said wifi connection
@@ -147,7 +148,8 @@ Q_SIGNALS:
 private:
     QCoro::Task<> addAndActivateConnectionDBus(const NMVariantMapMap &map, const QString &device, const QString &specificObject);
     QCoro::Task<> activateConnectionInternal(const QString &connection, const QString &device, const QString &specificParameter);
-    QCoro::Task<> addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password = QString());
+    QCoro::Task<>
+    addAndActivateConnectionInternal(const QString &device, const QString &specificParameter, const QString &password = QString(), bool metered = false);
     QCoro::Task<> deactivateConnectionInternal(const QString &connection, const QString &device);
     QCoro::Task<> removeConnectionInternal(const QString &connection);
     QCoro::Task<> requestScanInternal(const QString &interface = QString());
-- 
